
"""
Assignment 6: Making the Impossible Possible
Longest Common Subsequence (LCS)

Algorithms:
1. Naive recursion
2. Top-down dynamic programming with memoization
3. Bottom-up dynamic programming with tabulation
"""

import json
import time
from pathlib import Path


# Find the sequences folder relative to this Python file.
DATA_DIR = Path(__file__).resolve().parent / "sequences"

# Dataset sizes generated by sequence_generator.py.
DATASET_SIZES = [10, 20, 50, 100, 200, 500, 1000]

# Naive recursion becomes extremely slow as sequences get larger.
RECURSIVE_MAX_SIZE = 10


def lcs_recursive(seq1, seq2):
    """
    Calculate the LCS length using naive recursion.

    Time complexity: Exponential in the worst case.
    Space complexity: O(m + n) recursion stack.
    """

    def solve(i, j):
        if i == 0 or j == 0:
            return 0

        if seq1[i - 1] == seq2[j - 1]:
            return 1 + solve(i - 1, j - 1)

        return max(
            solve(i - 1, j),
            solve(i, j - 1)
        )

    return solve(len(seq1), len(seq2))


def lcs_memoization(seq1, seq2):
    """
    Calculate the LCS length using memoized dynamic programming.

    Uses an explicit stack to avoid Python's recursion limit.

    Time complexity: O(m * n).
    Space complexity: O(m * n).
    """

    m, n = len(seq1), len(seq2)
    memo = {}
    stack = [(m, n, False)]

    while stack:
        i, j, ready = stack.pop()
        key = (i, j)

        if key in memo:
            continue

        if i == 0 or j == 0:
            memo[key] = 0
            continue

        if not ready:
            # Revisit this state after its dependencies are calculated.
            stack.append((i, j, True))

            if seq1[i - 1] == seq2[j - 1]:
                dependency = (i - 1, j - 1)

                if dependency not in memo:
                    stack.append((dependency[0], dependency[1], False))
            else:
                dependencies = [(i - 1, j), (i, j - 1)]

                for di, dj in dependencies:
                    if (di, dj) not in memo:
                        stack.append((di, dj, False))

        else:
            if seq1[i - 1] == seq2[j - 1]:
                memo[key] = 1 + memo[(i - 1, j - 1)]
            else:
                memo[key] = max(
                    memo[(i - 1, j)],
                    memo[(i, j - 1)]
                )

    return memo[(m, n)]


def lcs_tabulation(seq1, seq2):
    """
    Calculate the LCS length using bottom-up dynamic programming.

    Time complexity: O(m * n).
    Space complexity: O(m * n).
    """

    m = len(seq1)
    n = len(seq2)

    # dp[i][j] stores the LCS length for the first i and j characters.
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if seq1[i - 1] == seq2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(
                    dp[i - 1][j],
                    dp[i][j - 1]
                )

    return dp[m][n]


def load_sequence(size):
    """
    Load a DNA sequence dataset by size.

    Example: size=10 loads sequences/dna_10.json.
    """

    filename = DATA_DIR / f"dna_{size}.json"

    with filename.open("r", encoding="utf-8") as file:
        data = json.load(file)

    if "sequence1" not in data or "sequence2" not in data:
        raise ValueError(
            f"{filename.name} must contain 'sequence1' and 'sequence2'."
        )

    return data["sequence1"], data["sequence2"]


def test_small_cases():
    """Test all three algorithms against known LCS answers."""

    print("=" * 70)
    print("TESTING ON SMALL CASES")
    print("=" * 70)

    test_cases = [
        ("AGGTAB", "GXTXAYB", 4),
        ("ABCDGH", "AEDFHR", 3),
        ("ABC", "AC", 2),
        ("", "ABC", 0),
        ("AAAA", "AA", 2),
        ("GCTA", "GCTA", 4),
        ("ABC", "XYZ", 0),
    ]

    algorithms = [
        ("Recursive", lcs_recursive),
        ("Memoization", lcs_memoization),
        ("Tabulation", lcs_tabulation),
    ]

    all_passed = True

    for seq1, seq2, expected in test_cases:
        print(
            f"\nTest: {seq1!r} vs {seq2!r} "
            f"| Expected LCS length: {expected}"
        )

        for name, algorithm in algorithms:
            try:
                result = algorithm(seq1, seq2)
                passed = result == expected

                print(
                    f"  {name}: {result} - "
                    f"{'PASS' if passed else 'FAIL'}"
                )

                if not passed:
                    all_passed = False

            except (RecursionError, MemoryError) as error:
                print(f"  {name}: ERROR - {error}")
                all_passed = False

    print(
        "\nOverall result:",
        "ALL TESTS PASSED" if all_passed else "SOME TESTS FAILED"
    )

    return all_passed


def time_recursive():
    """Benchmark naive recursion only on small datasets."""

    print("\n" + "=" * 70)
    print("TIMING NAIVE RECURSION")
    print("=" * 70)

    print(
        f"Naive recursion is limited to dataset sizes "
        f"of {RECURSIVE_MAX_SIZE} or smaller."
    )

    for size in DATASET_SIZES:
        if size > RECURSIVE_MAX_SIZE:
            continue

        try:
            seq1, seq2 = load_sequence(size)
        except (FileNotFoundError, json.JSONDecodeError, ValueError) as error:
            print(f"Skipping size {size}: {error}")
            continue

        start = time.perf_counter()

        try:
            result = lcs_recursive(seq1, seq2)
        except (RecursionError, MemoryError) as error:
            print(f"Size {size}: recursion could not finish: {error}")
            continue

        elapsed = time.perf_counter() - start

        print(
            f"Size {size}: LCS length = {result}, "
            f"time = {elapsed:.6f} seconds"
        )


def compare_all_approaches():
    """Compare algorithm runtimes and verify successful results agree."""

    print("\n" + "=" * 100)
    print("COMPARING ALL APPROACHES")
    print("=" * 100)

    header = (
        f"{'Size':<10}"
        f"{'Recursive':<20}"
        f"{'Memoization':<20}"
        f"{'Tabulation':<20}"
        f"{'Results Match?':<18}"
    )

    print(header)
    print("-" * len(header))

    for size in DATASET_SIZES:
        try:
            seq1, seq2 = load_sequence(size)
        except (FileNotFoundError, json.JSONDecodeError, ValueError) as error:
            print(f"{size:<10}Dataset unavailable: {error}")
            continue

        results = {}
        timings = {}

        # Run naive recursion only on the smallest dataset.
        if size <= RECURSIVE_MAX_SIZE:
            try:
                start = time.perf_counter()
                results["recursive"] = lcs_recursive(seq1, seq2)
                timings["recursive"] = time.perf_counter() - start
            except (RecursionError, MemoryError):
                results["recursive"] = None
                timings["recursive"] = None
        else:
            results["recursive"] = None
            timings["recursive"] = None

        # Run memoization and tabulation on every dataset.
        algorithms = [
            ("memoization", lcs_memoization),
            ("tabulation", lcs_tabulation),
        ]

        for name, algorithm in algorithms:
            try:
                start = time.perf_counter()
                results[name] = algorithm(seq1, seq2)
                timings[name] = time.perf_counter() - start
            except (RecursionError, MemoryError) as error:
                results[name] = None
                timings[name] = None
                print(f"Warning: {name} failed for size {size}: {error}")

        def format_time(elapsed):
            if elapsed is None:
                return "Skipped/error"
            return f"{elapsed:.6f}s"

        successful_results = [
            result for result in results.values()
            if result is not None
        ]

        successful_timings = [
            elapsed for elapsed in timings.values()
            if elapsed is not None
        ]

        # Require all three algorithms to succeed when recursion is
        # enabled, or both dynamic programming algorithms otherwise.
        expected_count = 3 if size <= RECURSIVE_MAX_SIZE else 2

        results_match = (
            len(successful_results) == expected_count
            and len(successful_timings) == expected_count
            and len(set(successful_results)) == 1
        )

        print(
            f"{size:<10}"
            f"{format_time(timings['recursive']):<20}"
            f"{format_time(timings['memoization']):<20}"
            f"{format_time(timings['tabulation']):<20}"
            f"{'Yes' if results_match else 'Check results':<18}"
        )

        if not results_match:
            print(f"  Result details: {results}")

    print("\nComparison complete.")


if __name__ == "__main__":
    print("DYNAMIC PROGRAMMING ASSIGNMENT - LONGEST COMMON SUBSEQUENCE\n")

    tests_passed = test_small_cases()

    if tests_passed:
        time_recursive()
        compare_all_approaches()
    else:
        print("\nFix failing correctness tests before benchmarking.")
